"""Writes the browser's side of the WebGPU driver for a build without
Emscripten (mrhi-0016): the EM_JS functions of the given C files as one
JavaScript module, whose export maulRhiImports(exports, module) returns
them for the page to put among the instance's `env` imports.

    gen_web_glue.py <out.mjs> <file.c>...

The functions keep their bodies as written; a few lines at the top give
them what Emscripten's runtime would: views of memory, the UTF-8 helpers,
the function table and a Module object, the page's when it passes one.
"""

import re
import sys

PRELUDE = """\
// Generated by tools/gen_web_glue.py from the EM_JS functions of
// {sources}; do not edit (mrhi-0016).
//
// maulRhiImports(exports, module) returns the functions for the page to
// put among the instance's `env` imports. `exports` returns the
// instance's exports once there is one; the program links with
// --export-table. `module`, if given, is the object the functions keep
// their state in, as Emscripten's Module: the driver's is its `mrhiGpu`.

export function maulRhiImports(exports, module) {{
    const Module = module || {{}};
    let HEAP8, HEAPU8, HEAP16, HEAPU16, HEAP32, HEAPU32, HEAPF32, HEAPF64;
    let buffer = null;
    // The views, made again when memory has grown.
    const refresh = () => {{
        const current = exports().memory.buffer;
        if (current !== buffer) {{
            buffer = current;
            HEAP8 = new Int8Array(buffer);
            HEAPU8 = new Uint8Array(buffer);
            HEAP16 = new Int16Array(buffer);
            HEAPU16 = new Uint16Array(buffer);
            HEAP32 = new Int32Array(buffer);
            HEAPU32 = new Uint32Array(buffer);
            HEAPF32 = new Float32Array(buffer);
            HEAPF64 = new Float64Array(buffer);
        }}
    }};
    const decoder = new TextDecoder();
    const encoder = new TextEncoder();
    // As Emscripten's: the text at a pointer, up to a NUL or the most
    // bytes given, or all of those with `ignoreNul`.
    const UTF8ToString = (pointer, most, ignoreNul) => {{
        refresh();
        if (!pointer) {{
            return '';
        }}
        const limit = most === undefined ? HEAPU8.length : Math.min(HEAPU8.length, pointer + most);
        let end = ignoreNul && most !== undefined ? limit : pointer;
        while (end < limit && HEAPU8[end] !== 0) {{
            ++end;
        }}
        return decoder.decode(HEAPU8.subarray(pointer, end));
    }};
    const lengthBytesUTF8 = text => encoder.encode(text).length;
    // As Emscripten's: at most `capacity` bytes with the NUL, never part
    // of a character; returns the bytes written before the NUL.
    const stringToUTF8 = (text, pointer, capacity) => {{
        refresh();
        if (!(capacity > 0)) {{
            return 0;
        }}
        const bytes = encoder.encode(text);
        let length = Math.min(bytes.length, capacity - 1);
        while (length > 0 && length < bytes.length && (bytes[length] & 0xc0) === 0x80) {{
            --length;
        }}
        HEAPU8.set(bytes.subarray(0, length), pointer);
        HEAPU8[pointer + length] = 0;
        return length;
    }};
    const getWasmTableEntry = index => exports().__indirect_function_table.get(index);
    return {{
"""

EPILOGUE = """\
    };
}
"""

HEAD = re.compile(r"\bEM_JS\s*\(")


def skip_quoted(text, at, quote):
    """The index past a JavaScript string or template literal."""
    at += 1
    while at < len(text):
        if text[at] == "\\":
            at += 2
            continue
        if text[at] == quote:
            return at + 1
        at += 1
    raise ValueError("an unterminated string")


def matching(text, at, opening, closing):
    """The index of the bracket closing the one at `at`, past strings and
    comments."""
    depth = 0
    while at < len(text):
        c = text[at]
        if c in "'\"`":
            at = skip_quoted(text, at, c)
            continue
        if text.startswith("//", at):
            at = text.index("\n", at)
            continue
        if text.startswith("/*", at):
            at = text.index("*/", at) + 2
            continue
        if c == opening:
            depth += 1
        elif c == closing:
            depth -= 1
            if depth == 0:
                return at
        at += 1
    raise ValueError("an unclosed " + opening)


def split_top(text):
    """Splits at the commas outside brackets."""
    parts, depth, start = [], 0, 0
    for at, c in enumerate(text):
        if c in "([{":
            depth += 1
        elif c in ")]}":
            depth -= 1
        elif c == "," and depth == 0:
            parts.append(text[start:at])
            start = at + 1
    parts.append(text[start:])
    return [part.strip() for part in parts]


def parameter_names(declaration):
    """The names of a C parameter list: the last identifier of each, or the
    name inside a function pointer's parentheses."""
    inner = declaration.strip()[1:-1].strip()
    if inner in ("", "void"):
        return []
    names = []
    for parameter in split_top(inner):
        pointer = re.search(r"\(\s*\*\s*(\w+)\s*\)", parameter)
        if pointer:
            names.append(pointer.group(1))
            continue
        match = re.search(r"(\w+)\s*(\[[^\]]*\])?\s*$", parameter)
        if not match:
            raise ValueError("a parameter without a name: " + parameter)
        names.append(match.group(1))
    return names


def functions_of(path):
    text = open(path, encoding="utf-8").read()
    found = []
    for head in HEAD.finditer(text):
        # Macro definitions name EM_JS without being one.
        line_start = text.rfind("\n", 0, head.start()) + 1
        if text[line_start:head.start()].lstrip().startswith("#"):
            continue
        close = matching(text, head.end() - 1, "(", ")")
        arguments = split_top(text[head.end():close])
        if len(arguments) != 4:
            raise ValueError(f"{path}: an EM_JS with {len(arguments)} arguments")
        name, parameters, body = arguments[1], arguments[2], arguments[3]
        if not (body.startswith("{") and body.endswith("}")):
            raise ValueError(f"{path}: {name}'s body is not a block")
        found.append((name, parameter_names(parameters), body[1:-1]))
    return found


def main():
    if len(sys.argv) < 3:
        sys.exit("usage: gen_web_glue.py <out.mjs> <file.c>...")
    out, sources = sys.argv[1], sys.argv[2:]
    seen = set()
    members = []
    for path in sources:
        for name, parameters, body in functions_of(path):
            if name in seen:
                sys.exit(f"gen_web_glue.py: {name} is defined twice")
            seen.add(name)
            lines = [line.rstrip() for line in body.strip("\n").split("\n")]
            # The body's own indentation, taken off and replaced by the
            # member's.
            indent = min((len(line) - len(line.lstrip()) for line in lines if line.strip()), default=0)
            inner = "\n".join(("            " + line[indent:]) if line.strip() else "" for line in lines)
            members.append(
                f"        {name}({', '.join(parameters)}) {{\n"
                "            refresh();\n"
                f"{inner}\n"
                "        },\n"
            )
    names = ", ".join(sorted({path.replace("\\", "/").rsplit("/", 1)[-1] for path in sources}))
    text = PRELUDE.format(sources=names) + "".join(members) + EPILOGUE
    with open(out, "w", encoding="utf-8", newline="\n") as file:
        file.write(text)


if __name__ == "__main__":
    try:
        main()
    except ValueError as error:
        sys.exit(f"gen_web_glue.py: {error}")
